CREATE TRIGGER "work_changes_writer" BEFORE INSERT ON "work_changes" WHEN foxrun_context('writer') IS NULL OR (foxrun_context('writer')='agent' AND coalesce(length(trim(NEW.session)),0)=0) OR (foxrun_context('writer') IN ('feeder','cron') AND coalesce(length(trim(NEW.source)),0)=0) BEGIN SELECT RAISE(ABORT,'writer requires session or feeder source'); END;
CREATE TRIGGER "work_changes_seq_insert" BEFORE INSERT ON "work_changes" BEGIN SELECT CASE WHEN NEW.seq<>(SELECT value+1 FROM _foxrun_sequence WHERE id=1) THEN RAISE(ABORT,'sequence must be allocated by the database') END; END;
CREATE TRIGGER "work_changes_seq_advance" AFTER INSERT ON "work_changes" BEGIN UPDATE _foxrun_sequence SET value=NEW.seq WHERE id=1; END;
