CREATE TRIGGER _foxrun_sequence_monotonic BEFORE UPDATE ON _foxrun_sequence WHEN NEW.id<>OLD.id OR NEW.value<>OLD.value+1 BEGIN SELECT RAISE(ABORT,'sequence only advances by one'); END;
CREATE TRIGGER _foxrun_sequence_event BEFORE UPDATE ON _foxrun_sequence WHEN NOT (EXISTS(SELECT 1 FROM "work_changes" WHERE seq=NEW.value) OR EXISTS(SELECT 1 FROM "work_comments" WHERE seq=NEW.value) OR EXISTS(SELECT 1 FROM "work_attachments" WHERE seq=NEW.value) OR EXISTS(SELECT 1 FROM "base_approvals" WHERE seq=NEW.value) OR EXISTS(SELECT 1 FROM "base_receipts" WHERE seq=NEW.value)) BEGIN SELECT RAISE(ABORT,'sequence requires its appended event'); END;
CREATE TRIGGER "amazon_account_markets_created" AFTER INSERT ON "amazon_account_markets" WHEN foxrun_context('writer') IS NOT 'schema' BEGIN INSERT INTO work_changes (seq,workspace,subject_type,subject_id,field,old_value,new_value,action,actor,session,source,occurred_at,recorded_at,subject_version,summary,refs) VALUES ((SELECT value+1 FROM _foxrun_sequence WHERE id=1),NEW.workspace,'account-market',NEW.id,NULL,NULL,NULL,foxrun_creation_action('account-market',NULL),foxrun_context('actor'),foxrun_context('session'),foxrun_context('source'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL,foxrun_context('reason'),json_array(json_object('initial',json_object()))); END;
CREATE TRIGGER "amazon_account_markets_id_immutable" BEFORE UPDATE OF id ON "amazon_account_markets" WHEN NEW.id<>OLD.id BEGIN SELECT RAISE(ABORT,'hidden id is immutable'); END;
CREATE TRIGGER "amazon_accounts_created" AFTER INSERT ON "amazon_accounts" WHEN foxrun_context('writer') IS NOT 'schema' BEGIN INSERT INTO work_changes (seq,workspace,subject_type,subject_id,field,old_value,new_value,action,actor,session,source,occurred_at,recorded_at,subject_version,summary,refs) VALUES ((SELECT value+1 FROM _foxrun_sequence WHERE id=1),foxrun_context('workspace'),'account',NEW.id,NULL,NULL,NULL,foxrun_creation_action('account',NULL),foxrun_context('actor'),foxrun_context('session'),foxrun_context('source'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL,foxrun_context('reason'),json_array(json_object('initial',json_object()))); END;
