CREATE TRIGGER "amazon_compliance_cases_cancellation_update" BEFORE UPDATE ON "amazon_compliance_cases" WHEN NEW.status='canceled' AND coalesce(length(trim(foxrun_context('reason'))),0)=0 BEGIN SELECT RAISE(ABORT,'canceled requires a reason'); END;
