CREATE TRIGGER "people_draft_facts_state_frozen_new_insert" BEFORE INSERT ON "people_draft_facts" WHEN EXISTS(SELECT 1 FROM people_drafts d WHERE d.id=NEW.draft AND (d.status<>'draft' OR EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=d.id AND a.action='approved' AND a.authorization_valid=1 AND a.version=d.version))) BEGIN SELECT RAISE(ABORT,'a fact line changes only while its draft is a draft and before his yes'); END;
CREATE TRIGGER "people_draft_facts_state_frozen_update" BEFORE UPDATE ON "people_draft_facts" WHEN EXISTS(SELECT 1 FROM people_drafts d WHERE d.id=OLD.draft AND (d.status<>'draft' OR (EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=d.id AND a.action='approved' AND a.authorization_valid=1 AND a.version=d.version) AND NOT (NEW.text IS OLD.text AND NEW.checked_at IS OLD.checked_at AND NEW.source_type IS OLD.source_type AND NEW.source_id IS OLD.source_id AND NEW.source_ref IS OLD.source_ref AND lower(trim(coalesce(NEW.reviewed_by,'')))='@person@')))) BEGIN SELECT RAISE(ABORT,'a fact line changes only while its draft is a draft and before his yes'); END;
CREATE TRIGGER "people_draft_facts_state_draft_never_changes_on_conflict_insert" BEFORE INSERT ON "people_draft_facts" WHEN EXISTS(SELECT 1 FROM people_draft_facts f WHERE f.id=NEW.id AND f.draft IS NOT NEW.draft) BEGIN SELECT RAISE(ABORT,'the draft of a fact line never changes'); END;
CREATE TRIGGER "people_draft_facts_state_draft_never_changes_update" BEFORE UPDATE ON "people_draft_facts" WHEN NEW.draft IS NOT OLD.draft BEGIN SELECT RAISE(ABORT,'the draft of a fact line never changes'); END;
CREATE TRIGGER "people_draft_facts_state_reviewer_person_new_insert" BEFORE INSERT ON "people_draft_facts" WHEN lower(trim(NEW.reviewed_by))='@person@' AND NOT EXISTS(SELECT 1 FROM people_drafts d WHERE d.id=NEW.draft AND EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=d.id AND a.workspace=d.workspace AND a.action='approved' AND (a.authorization_valid=1 OR (coalesce(foxrun_context('import'),0)=1 AND a.authorization_valid=0)) AND a.version=d.version AND a.approved_sha256=d.content_hash)) BEGIN SELECT RAISE(ABORT,'the reviewer @person@ needs his approval row on the draft'); END;
CREATE TRIGGER "people_draft_facts_state_reviewer_person_update" BEFORE UPDATE ON "people_draft_facts" WHEN lower(trim(NEW.reviewed_by))='@person@' AND NEW.reviewed_by IS NOT OLD.reviewed_by AND NOT EXISTS(SELECT 1 FROM people_drafts d WHERE d.id=NEW.draft AND EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=d.id AND a.workspace=d.workspace AND a.action='approved' AND (a.authorization_valid=1 OR (coalesce(foxrun_context('import'),0)=1 AND a.authorization_valid=0)) AND a.version=d.version AND a.approved_sha256=d.content_hash)) BEGIN SELECT RAISE(ABORT,'the reviewer @person@ needs his approval row on the draft'); END;
CREATE TRIGGER "people_draft_facts_review_reset" AFTER UPDATE OF "text","source_type","source_id","source_ref" ON "people_draft_facts" WHEN OLD."reviewed_by" IS NOT NULL AND NEW."reviewed_by" IS OLD."reviewed_by" AND (NEW."text" IS NOT OLD."text" OR NEW."source_type" IS NOT OLD."source_type" OR NEW."source_id" IS NOT OLD."source_id" OR NEW."source_ref" IS NOT OLD."source_ref") BEGIN UPDATE "people_draft_facts" SET "reviewed_by"=NULL WHERE id=NEW.id; END;
