CREATE TRIGGER "people_draft_facts_checked_at_changed" AFTER UPDATE OF "checked_at" ON "people_draft_facts" WHEN OLD."checked_at" IS NOT NEW."checked_at" AND foxrun_context('writer') IS NOT 'schema' BEGIN INSERT INTO work_changes (seq,workspace,subject_type,subject_id,field,old_value,new_value,action,actor,session,source,occurred_at,recorded_at,subject_version,summary,refs) VALUES ((SELECT value+1 FROM _foxrun_sequence WHERE id=1),foxrun_context('workspace'),'draft-fact',NEW.id,'checked_at',CAST(OLD."checked_at" AS TEXT),CAST(NEW."checked_at" AS TEXT),foxrun_action('draft-fact','checked_at',CAST(OLD."checked_at" AS TEXT),CAST(NEW."checked_at" AS TEXT)),foxrun_context('actor'),foxrun_context('session'),foxrun_context('source'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL,foxrun_context('reason'),NULL); END;
