CREATE TRIGGER "people_draft_facts_id_immutable" BEFORE UPDATE OF id ON "people_draft_facts" WHEN NEW.id<>OLD.id BEGIN SELECT RAISE(ABORT,'hidden id is immutable'); END;
CREATE TRIGGER "people_drafts_cancellation_insert" BEFORE INSERT ON "people_drafts" WHEN NEW.status='canceled' AND coalesce(length(trim(foxrun_context('reason'))),0)=0 BEGIN SELECT RAISE(ABORT,'canceled requires a reason'); END;
CREATE TRIGGER "people_drafts_cancellation_update" BEFORE UPDATE ON "people_drafts" WHEN NEW.status='canceled' AND coalesce(length(trim(foxrun_context('reason'))),0)=0 BEGIN SELECT RAISE(ABORT,'canceled requires a reason'); END;
CREATE TRIGGER "people_drafts_created_at_required_insert" BEFORE INSERT ON "people_drafts" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."created_at" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires created_at'); END;
CREATE TRIGGER "people_drafts_updated_at_required_insert" BEFORE INSERT ON "people_drafts" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."updated_at" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires updated_at'); END;
CREATE TRIGGER "people_drafts_state_holds_his_yes_new_insert" BEFORE INSERT ON "people_drafts" WHEN NEW.status IN ('approved','sent') AND (coalesce(length(trim(NEW.text)),0)=0 OR NOT EXISTS(SELECT 1 FROM base_approvals a WHERE a.seq=NEW.approval AND a.subject_type='draft' AND a.subject_id=NEW.id AND a.workspace=NEW.workspace AND a.action='approved' AND (a.authorization_valid=1 OR (coalesce(foxrun_context('import'),0)=1 AND a.authorization_valid=0)) AND a.version=NEW.version AND a.approved_sha256=NEW.content_hash) OR EXISTS(SELECT 1 FROM base_approvals r WHERE r.subject_type='draft' AND r.subject_id=NEW.id AND (r.action='rejected' OR (r.action='edited' AND NEW.status<>'sent')) AND r.seq>NEW.approval) OR EXISTS(SELECT 1 FROM work_changes x WHERE x.subject_type='draft' AND x.subject_id=NEW.id AND x.field IN ('text','content_hash') AND x.seq>NEW.approval) OR EXISTS(SELECT 1 FROM work_changes x JOIN people_draft_facts f ON f.id=x.subject_id WHERE x.subject_type='draft-fact' AND f.draft=NEW.id AND x.seq>NEW.approval AND NOT (x.field='reviewed_by' AND lower(trim(coalesce(x.new_value,'')))='@person@'))) BEGIN SELECT RAISE(ABORT,'approved and sent need his approval row for this exact version and hash, and no later no or edit before sent'); END;
CREATE TRIGGER "people_drafts_state_sent_needs_read_back_new_insert" BEFORE INSERT ON "people_drafts" WHEN NEW.status='sent' AND NOT EXISTS(SELECT 1 FROM people_messages m WHERE m.id=NEW.sent_message AND m.conversation=NEW.conversation AND m.direction='outbound' AND m.text=NEW.text AND coalesce(length(trim(m.source_message_id)),0)>0) BEGIN SELECT RAISE(ABORT,'sent needs the read-back: an outbound message of this conversation with this exact text and its platform id'); END;
CREATE TRIGGER "people_drafts_state_starts_as_draft_insert" BEFORE INSERT ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND NEW.status IN ('approved','sent') BEGIN SELECT RAISE(ABORT,'a new draft row is not approved or sent; those need his approval row'); END;
CREATE TRIGGER "people_drafts_state_draft_to_sent_update" BEFORE UPDATE ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND OLD.status='draft' AND NEW.status='sent' BEGIN SELECT RAISE(ABORT,'a draft moves to sent only after approved'); END;
CREATE TRIGGER "people_drafts_state_holds_his_yes_update" BEFORE UPDATE ON "people_drafts" WHEN NEW.status IN ('approved','sent') AND (((NEW.text IS NOT OLD.text OR NEW.content_hash IS NOT OLD.content_hash OR NEW.version IS NOT OLD.version)) OR coalesce(length(trim(NEW.text)),0)=0 OR NOT EXISTS(SELECT 1 FROM base_approvals a WHERE a.seq=NEW.approval AND a.subject_type='draft' AND a.subject_id=NEW.id AND a.workspace=NEW.workspace AND a.action='approved' AND (a.authorization_valid=1 OR (coalesce(foxrun_context('import'),0)=1 AND a.authorization_valid=0)) AND a.version=NEW.version AND a.approved_sha256=NEW.content_hash) OR EXISTS(SELECT 1 FROM base_approvals r WHERE r.subject_type='draft' AND r.subject_id=NEW.id AND (r.action='rejected' OR (r.action='edited' AND OLD.status<>'sent')) AND r.seq>NEW.approval) OR EXISTS(SELECT 1 FROM work_changes x WHERE x.subject_type='draft' AND x.subject_id=NEW.id AND x.field IN ('text','content_hash') AND x.seq>NEW.approval) OR EXISTS(SELECT 1 FROM work_changes x JOIN people_draft_facts f ON f.id=x.subject_id WHERE x.subject_type='draft-fact' AND f.draft=NEW.id AND x.seq>NEW.approval AND NOT (x.field='reviewed_by' AND lower(trim(coalesce(x.new_value,'')))='@person@'))) BEGIN SELECT RAISE(ABORT,'approved and sent need his approval row for this exact version and hash, and no later no or edit before sent'); END;
CREATE TRIGGER "people_drafts_state_sent_needs_read_back_update" BEFORE UPDATE ON "people_drafts" WHEN NEW.status='sent' AND NOT EXISTS(SELECT 1 FROM people_messages m WHERE m.id=NEW.sent_message AND m.conversation=NEW.conversation AND m.direction='outbound' AND m.text=NEW.text AND coalesce(length(trim(m.source_message_id)),0)>0) BEGIN SELECT RAISE(ABORT,'sent needs the read-back: an outbound message of this conversation with this exact text and its platform id'); END;
CREATE TRIGGER "people_drafts_state_words_frozen_update" BEFORE UPDATE ON "people_drafts" WHEN OLD.status<>'draft' AND (NEW.text IS NOT OLD.text OR NEW.content_hash IS NOT OLD.content_hash) BEGIN SELECT RAISE(ABORT,'the text and its hash change only while the status is draft; an edit makes a new version row'); END;
CREATE TRIGGER "people_drafts_state_approved_needs_facts_decided_update" BEFORE UPDATE ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND OLD.status='draft' AND NEW.status='approved' AND EXISTS(SELECT 1 FROM people_draft_facts f WHERE f.draft=NEW.id AND f.source_id IS NULL AND lower(trim(coalesce(f.reviewed_by,'')))<>'@person@') BEGIN SELECT RAISE(ABORT,'a fact with no record waits for his decision'); END;
CREATE TRIGGER "people_drafts_state_replaced_needs_later_version_update" BEFORE UPDATE ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND OLD.status IN ('draft','approved') AND NEW.status='replaced' AND NOT EXISTS(SELECT 1 FROM people_drafts x WHERE x.family_id=NEW.family_id AND x.version>NEW.version) BEGIN SELECT RAISE(ABORT,'replaced needs a later version in the same family'); END;
CREATE TRIGGER "people_drafts_state_approved_to_draft_update" BEFORE UPDATE ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND OLD.status='approved' AND NEW.status='draft' BEGIN SELECT RAISE(ABORT,'approved does not go back to draft; an edit makes a new version row'); END;
CREATE TRIGGER "people_drafts_state_ends_update" BEFORE UPDATE ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND OLD.status IN ('sent','skipped','replaced') AND NEW.status IS NOT OLD.status BEGIN SELECT RAISE(ABORT,'sent, skipped, and replaced are ends'); END;
CREATE TRIGGER "people_drafts_state_one_open_draft_insert" BEFORE INSERT ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND NEW.status IN ('draft','approved') AND EXISTS(SELECT 1 FROM people_drafts x WHERE x.conversation=NEW.conversation AND x.status IN ('draft','approved') AND NOT (x.family_id=NEW.family_id AND x.version<NEW.version AND (coalesce((SELECT h.agent FROM people_conversations_in_hand h WHERE h.draft=x.id),'')=coalesce(foxrun_context('actor'),'') OR coalesce((SELECT h.stale FROM people_conversations_in_hand h WHERE h.draft=x.id),1)=1))) BEGIN SELECT RAISE(ABORT,'the conversation is in hand: one open draft per conversation; a later version of its family replaces it, by its own agent or when it is stale'); END;
CREATE TRIGGER "people_drafts_state_one_open_draft_moved_update" BEFORE UPDATE ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND NEW.conversation IS NOT OLD.conversation AND NEW.status IN ('draft','approved') AND EXISTS(SELECT 1 FROM people_drafts x WHERE x.conversation=NEW.conversation AND x.status IN ('draft','approved') AND x.id<>NEW.id) BEGIN SELECT RAISE(ABORT,'the conversation is in hand: one open draft per conversation'); END;
CREATE TRIGGER "people_drafts_state_version_frozen_after_yes_update" BEFORE UPDATE ON "people_drafts" WHEN EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=OLD.id AND a.action='approved' AND a.authorization_valid=1 AND a.version=OLD.version) AND (NEW.text IS NOT OLD.text OR NEW.content_hash IS NOT OLD.content_hash OR NEW.version IS NOT OLD.version OR NEW.family_id IS NOT OLD.family_id OR NEW.workspace IS NOT OLD.workspace OR NEW.conversation IS NOT OLD.conversation OR NEW.author IS NOT OLD.author OR NEW.contact IS NOT OLD.contact OR NEW.function IS NOT OLD.function OR NEW.model IS NOT OLD.model OR NEW.requested_by IS NOT OLD.requested_by OR NEW.request IS NOT OLD.request OR NEW.created_at IS NOT OLD.created_at) BEGIN SELECT RAISE(ABORT,'approved and sent need his approval row for this exact version and hash; his yes freezes this version; an edit makes a new version row'); END;
CREATE TRIGGER "people_drafts_state_version_stays_on_conflict_insert" BEFORE INSERT ON "people_drafts" WHEN EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=NEW.id AND a.action='approved' AND a.authorization_valid=1) OR (EXISTS(SELECT 1 FROM people_drafts d WHERE (d.id=NEW.id OR (d.family_id=NEW.family_id AND d.version=NEW.version)) AND (d.status<>'draft' OR EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=d.id AND a.action='approved' AND a.authorization_valid=1 AND a.version=d.version)))) BEGIN SELECT RAISE(ABORT,'a draft version with his yes or an end state cannot be replaced'); END;
CREATE TRIGGER "people_drafts_state_version_stays_on_update_conflict_update" BEFORE UPDATE ON "people_drafts" WHEN EXISTS(SELECT 1 FROM people_drafts d WHERE d.id<>OLD.id AND d.family_id=NEW.family_id AND d.version=NEW.version AND (d.status<>'draft' OR EXISTS(SELECT 1 FROM base_approvals a WHERE a.subject_type='draft' AND a.subject_id=d.id AND a.action='approved' AND a.authorization_valid=1 AND a.version=d.version))) BEGIN SELECT RAISE(ABORT,'an update conflict cannot replace a draft version with his yes or an end state'); END;
CREATE TRIGGER "people_drafts_created" AFTER INSERT ON "people_drafts" WHEN foxrun_context('writer') IS NOT 'schema' BEGIN INSERT INTO work_changes (seq,workspace,subject_type,subject_id,field,old_value,new_value,action,actor,session,source,occurred_at,recorded_at,subject_version,summary,refs) VALUES ((SELECT value+1 FROM _foxrun_sequence WHERE id=1),NEW.workspace,'draft',NEW.id,NULL,NULL,NULL,foxrun_creation_action('draft',NEW.status),foxrun_context('actor'),foxrun_context('session'),foxrun_context('source'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),CAST(NEW.version AS TEXT),foxrun_context('reason'),json_array(json_object('initial',json_object('status',CAST(NEW."status" AS TEXT))))); END;
