CREATE TRIGGER "people_drafts_version_moves" BEFORE UPDATE OF "text","content_hash" ON "people_drafts" WHEN coalesce(foxrun_context('import'),0)=0 AND NEW.version IS OLD.version AND (NEW."text" IS NOT OLD."text" OR NEW."content_hash" IS NOT OLD."content_hash") BEGIN SELECT RAISE(ABORT,'a change of text or content_hash advances the version'); END;
