CREATE TRIGGER "work_attachments_occurred_at_required_insert" BEFORE INSERT ON "work_attachments" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."occurred_at" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires occurred_at'); END;
CREATE TRIGGER "work_attachments_recorded_at_required_insert" BEFORE INSERT ON "work_attachments" WHEN (1) AND NEW."recorded_at" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires recorded_at'); END;
CREATE TRIGGER "work_attachments_session_required_insert" BEFORE INSERT ON "work_attachments" WHEN (foxrun_context('writer')='agent') AND NEW."session" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires session'); END;
CREATE TRIGGER "work_attachments_session_required_update" BEFORE UPDATE ON "work_attachments" WHEN (foxrun_context('writer')='agent') AND NEW."session" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires session'); END;
CREATE TRIGGER "work_attachments_source_required_insert" BEFORE INSERT ON "work_attachments" WHEN (foxrun_context('writer') IN ('feeder','cron')) AND NEW."source" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires source'); END;
CREATE TRIGGER "work_attachments_source_required_update" BEFORE UPDATE ON "work_attachments" WHEN (foxrun_context('writer') IN ('feeder','cron')) AND NEW."source" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires source'); END;
CREATE TRIGGER "work_bugs_cancellation_insert" BEFORE INSERT ON "work_bugs" WHEN NEW.status='canceled' AND coalesce(length(trim(foxrun_context('reason'))),0)=0 BEGIN SELECT RAISE(ABORT,'canceled requires a reason'); END;
CREATE TRIGGER "work_bugs_cancellation_update" BEFORE UPDATE ON "work_bugs" WHEN NEW.status='canceled' AND coalesce(length(trim(foxrun_context('reason'))),0)=0 BEGIN SELECT RAISE(ABORT,'canceled requires a reason'); END;
CREATE TRIGGER "work_bugs_created_at_required_insert" BEFORE INSERT ON "work_bugs" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."created_at" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires created_at'); END;
CREATE TRIGGER "work_bugs_status_required_insert" BEFORE INSERT ON "work_bugs" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."status" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires status'); END;
CREATE TRIGGER "work_bugs_status_required_update" BEFORE UPDATE OF "status" ON "work_bugs" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."status" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires status'); END;
CREATE TRIGGER "work_bugs_updated_at_required_insert" BEFORE INSERT ON "work_bugs" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."updated_at" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires updated_at'); END;
CREATE TRIGGER "work_bugs_created" AFTER INSERT ON "work_bugs" WHEN foxrun_context('writer') IS NOT 'schema' BEGIN INSERT INTO work_changes (seq,workspace,subject_type,subject_id,field,old_value,new_value,action,actor,session,source,occurred_at,recorded_at,subject_version,summary,refs) VALUES ((SELECT value+1 FROM _foxrun_sequence WHERE id=1),NEW.workspace,'bug',NEW.id,NULL,NULL,NULL,foxrun_creation_action('bug',NEW.status),foxrun_context('actor'),foxrun_context('session'),foxrun_context('source'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL,foxrun_context('reason'),json_array(json_object('initial',json_object('status',CAST(NEW."status" AS TEXT))))); END;
CREATE TRIGGER "work_bugs_status_changed" AFTER UPDATE OF "status" ON "work_bugs" WHEN OLD."status" IS NOT NEW."status" AND foxrun_context('writer') IS NOT 'schema' BEGIN INSERT INTO work_changes (seq,workspace,subject_type,subject_id,field,old_value,new_value,action,actor,session,source,occurred_at,recorded_at,subject_version,summary,refs) VALUES ((SELECT value+1 FROM _foxrun_sequence WHERE id=1),NEW.workspace,'bug',NEW.id,'status',CAST(OLD."status" AS TEXT),CAST(NEW."status" AS TEXT),foxrun_action('bug','status',CAST(OLD."status" AS TEXT),CAST(NEW."status" AS TEXT)),foxrun_context('actor'),foxrun_context('session'),foxrun_context('source'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL,foxrun_context('reason'),NULL); END;
CREATE TRIGGER "work_bugs_id_immutable" BEFORE UPDATE OF id ON "work_bugs" WHEN NEW.id<>OLD.id BEGIN SELECT RAISE(ABORT,'hidden id is immutable'); END;
