CREATE TRIGGER "work_links_created_at_required_insert" BEFORE INSERT ON "work_links" WHEN (coalesce(foxrun_context('import'),0)=0) AND NEW."created_at" IS NULL BEGIN SELECT RAISE(ABORT,'new row requires created_at'); END;
