CREATE TRIGGER "work_links_created" AFTER INSERT ON "work_links" WHEN foxrun_context('writer') IS NOT 'schema' BEGIN INSERT INTO work_changes (seq,workspace,subject_type,subject_id,field,old_value,new_value,action,actor,session,source,occurred_at,recorded_at,subject_version,summary,refs) VALUES ((SELECT value+1 FROM _foxrun_sequence WHERE id=1),NEW.workspace,'link',NEW.id,NULL,NULL,NULL,foxrun_creation_action('link',NULL),foxrun_context('actor'),foxrun_context('session'),foxrun_context('source'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL,foxrun_context('reason'),json_array(json_object('initial',json_object()))); END;
CREATE TRIGGER "work_links_id_immutable" BEFORE UPDATE OF id ON "work_links" WHEN NEW.id<>OLD.id BEGIN SELECT RAISE(ABORT,'hidden id is immutable'); END;
