CREATE TRIGGER "people_pipeline_stages_choice_update" BEFORE UPDATE ON people_pipeline_stages WHEN NOT EXISTS(SELECT 1 FROM people_pipelines p WHERE p.id=NEW.pipeline AND ((p.name='clients' AND NEW.stage IN ('identified','conversation','qualified','offered','won','lost')) OR (p.name='creators' AND NEW.stage IN ('outreach','selection','shipment','production','payment','renewal','closed')) OR (p.name='ventures' AND NEW.stage IN ('idea','exploring','committed','building','launched','parked')))) BEGIN SELECT RAISE(ABORT,'stage is not allowed by its linked pipeline'); END;
CREATE TRIGGER "amazon_accounts_amazon_update" BEFORE UPDATE ON amazon_accounts WHEN NOT EXISTS(SELECT 1 FROM commerce_accounts WHERE id=NEW.id AND source_system='amazon') BEGIN SELECT RAISE(ABORT,'Amazon account must extend Amazon commerce account'); END;
CREATE TRIGGER work_attachments_page_version BEFORE INSERT ON work_attachments WHEN NEW.subject_type='page' AND NEW.action='published' BEGIN SELECT CASE WHEN coalesce(json_valid(NEW.payload),0)=0 THEN RAISE(ABORT,'page publication requires version payload') END; SELECT CASE WHEN coalesce(length(trim(CAST(json_extract(NEW.payload,'$.version') AS TEXT))),0)=0 THEN RAISE(ABORT,'page publication requires version payload') END; END;
CREATE TRIGGER people_pipeline_stages_referenced BEFORE UPDATE OF pipeline ON people_pipeline_stages WHEN EXISTS(SELECT 1 FROM people_opportunities o WHERE o.stage=NEW.id AND o.pipeline IS NOT NEW.pipeline) BEGIN SELECT RAISE(ABORT,'linked opportunities require the same pipeline'); END;
CREATE TRIGGER people_pipelines_stage_choices BEFORE UPDATE OF name ON people_pipelines WHEN EXISTS(SELECT 1 FROM people_pipeline_stages s WHERE s.pipeline=NEW.id AND NOT ((NEW.name='clients' AND s.stage IN ('identified','conversation','qualified','offered','won','lost')) OR (NEW.name='creators' AND s.stage IN ('outreach','selection','shipment','production','payment','renewal','closed')) OR (NEW.name='ventures' AND s.stage IN ('idea','exploring','committed','building','launched','parked')))) BEGIN SELECT RAISE(ABORT,'pipeline name conflicts with its linked stages'); END;
